/* Reset & base */
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #2d2a4a;
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 18px;
  line-height: 1.5;
  color: #f0eef8;
  padding: 16px;
}

/* Game board */
.game-board {
  background: #3d3a5c;
  border-radius: 24px;
  padding: 32px 24px;
  width: 100%;
  max-width: 420px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 20px;
}

h1 {
  font-size: 1.8rem;
  font-weight: 700;
  letter-spacing: 2px;
  color: #ffd166;
  text-transform: uppercase;
}

/* Pet drawn with CSS */
.pet-container {
  width: 120px;
  height: 120px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.pet {
  width: 100px;
  height: 100px;
  position: relative;
}

.pet-body {
  width: 100%;
  height: 100%;
  background: #ff9f68;
  border-radius: 50% 50% 45% 45%;
  position: relative;
  box-shadow: inset -8px -8px 0 rgba(0,0,0,0.1), 0 6px 0 #c47a4a;
  transition: transform 0.2s;
}

.pet-eye {
  width: 16px;
  height: 16px;
  background: #2d2a4a;
  border-radius: 50%;
  position: absolute;
  top: 30px;
}

.pet-eye.left { left: 22px; }
.pet-eye.right { right: 22px; }

.pet-mouth {
  width: 24px;
  height: 12px;
  border-bottom: 4px solid #2d2a4a;
  border-radius: 0 0 50% 50%;
  position: absolute;
  bottom: 28px;
  left: 50%;
  transform: translateX(-50%);
}

/* Mood text */
.mood {
  font-size: 1.1rem;
  font-weight: 600;
  color: #ffd166;
  text-align: center;
  min-height: 1.6em;
  transition: color 0.3s;
}

/* Stats */
.stats {
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.stat {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.stat-label {
  font-size: 0.95rem;
  font-weight: 600;
  color: #b8b3d6;
  text-transform: uppercase;
  letter-spacing: 1px;
}

.bar-bg {
  width: 100%;
  height: 20px;
  background: #2d2a4a;
  border-radius: 10px;
  overflow: hidden;
  box-shadow: inset 0 2px 4px rgba(0,0,0,0.3);
}

.bar {
  height: 100%;
  border-radius: 10px;
  transition: width 0.4s ease;
}

.bar.hunger { background: #ff6b6b; }
.bar.happiness { background: #ffd166; }
.bar.energy { background: #6bcb77; }

/* Controls */
.controls {
  display: flex;
  gap: 12px;
  width: 100%;
  flex-wrap: wrap;
  justify-content: center;
}

.btn {
  flex: 1 1 0;
  min-width: 90px;
  padding: 14px 16px;
  font-size: 1rem;
  font-weight: 700;
  font-family: inherit;
  color: #2d2a4a;
  background: #ffd166;
  border: none;
  border-radius: 12px;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s, box-shadow 0.15s;
  box-shadow: 0 4px 0 #c4a03e;
  text-transform: uppercase;
  letter-spacing: 1px;
}

.btn:hover {
  background: #ffe08a;
  box-shadow: 0 4px 0 #c4a03e;
}

.btn:focus-visible {
  outline: 3px solid #6bcb77;
  outline-offset: 2px;
}

.btn:active {
  transform: translateY(3px);
  box-shadow: 0 1px 0 #c4a03e;
}

/* Responsive */
@media (max-width: 400px) {
  .game-board {
    padding: 24px 16px;
  }
  h1 {
    font-size: 1.5rem;
  }
  .btn {
    min-width: 80px;
    padding: 12px 10px;
    font-size: 0.95rem;
  }
}

// Game state
const state = {
  hunger: 50,
  happiness: 50,
  energy: 50
};

// DOM elements
const hungerBar = document.getElementById('hunger-bar');
const happinessBar = document.getElementById('happiness-bar');
const energyBar = document.getElementById('energy-bar');
const moodText = document.getElementById('mood-text');
const feedBtn = document.getElementById('feed-btn');
const playBtn = document.getElementById('play-btn');
const sleepBtn = document.getElementById('sleep-btn');

// Update UI
function updateUI() {
  hungerBar.style.width = state.hunger + '%';
  happinessBar.style.width = state.happiness + '%';
  energyBar.style.width = state.energy + '%';

  // Update ARIA values
  hungerBar.parentElement.setAttribute('aria-valuenow', state.hunger);
  happinessBar.parentElement.setAttribute('aria-valuenow', state.happiness);
  energyBar.parentElement.setAttribute('aria-valuenow', state.energy);

  // Determine mood
  let mood = '';
  const avg = (state.hunger + state.happiness + state.energy) / 3;

  if (state.hunger < 20) mood = 'Your pet is very hungry!';
  else if (state.energy < 20) mood = 'Your pet is exhausted...';
  else if (state.happiness < 20) mood = 'Your pet is sad.';
  else if (avg > 80) mood = 'Your pet is thriving!';
  else if (avg > 60) mood = 'Your pet is happy!';
  else if (avg > 40) mood = 'Your pet is okay.';
  else mood = 'Your pet needs attention.';

  moodText.textContent = mood;

  // Change mood color based on state
  if (state.hunger < 20 || state.energy < 20 || state.happiness < 20) {
    moodText.style.color = '#ff6b6b';
  } else if (avg > 60) {
    moodText.style.color = '#ffd166';
  } else {
    moodText.style.color = '#b8b3d6';
  }
}

// Clamp values
function clamp(value) {
  return Math.max(0, Math.min(100, value));
}

// Actions
function feed() {
  state.hunger = clamp(state.hunger + 20);
  state.energy = clamp(state.energy - 5);
  updateUI();
}

function play() {
  state.happiness = clamp(state.happiness + 20);
  state.energy = clamp(state.energy - 15);
  state.hunger = clamp(state.hunger - 10);
  updateUI();
}

function sleep() {
  state.energy = clamp(state.energy + 25);
  state.hunger = clamp(state.hunger - 5);
  updateUI();
}

// Event listeners
feedBtn.addEventListener('click', feed);
playBtn.addEventListener('click', play);
sleepBtn.addEventListener('click', sleep);

// Initial render
updateUI();
